public class LayeredAppTests{static void check(boolean ok,String m){if(!ok)throw new AssertionError(m);}public static void main(String[]x){TaskService s=new TaskService();int before=s.count();s.add("Test");check(s.count()==before+1,"count increments");try{s.add("");throw new AssertionError("expected exception");}catch(IllegalArgumentException expected){}System.out.println("2 tests passed");}}
